export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full min-h-screen bg-primary text-accent p-4 sm:p-8 lg:p-12",
}

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const siteUrl = "https://riano.ca";
  const pathname = language === "fr"
    ? "/fr/services/core-web-vitals-performance/"
    : "/en/services/core-web-vitals-performance/";
  const pageUrl = `${siteUrl}${pathname}`;
  const title = getLocaleValue<string>(language, "services.cwv.meta.title") || "";
  const description = getLocaleValue<string>(language, "services.cwv.meta.description") || "";
  const faqItems = getLocaleValue<{
    q: string;
    a: string;
  }[]>(language, "services.cwv.sections.faq.items") || [];
  const jsonLd = buildJsonLd({
    siteUrl,
    pageUrl,
    lang: language,
    title,
    description,
    providerName: "Juan Pablo Riano",
    providerUrl: siteUrl,
    areaServed: ["Montréal", "Québec", "Canada", "United States"],
    offers: [
      {
        name: getLocaleValue<string>(language, "services.cwv.schema.offer1.name") || "",
        description: getLocaleValue<string>(language, "services.cwv.schema.offer1.desc") || "",
      },
      {
        name: getLocaleValue<string>(language, "services.cwv.schema.offer2.name") || "",
        description: getLocaleValue<string>(language, "services.cwv.schema.offer2.desc") || "",
      },
    ],
    faqItems,
  });
  const alternates = [
    { hrefLang: "en", href: `${siteUrl}/en/services/core-web-vitals-performance/` },
    { hrefLang: "fr", href: `${siteUrl}/fr/services/core-web-vitals-performance/` },
    { hrefLang: "x-default", href: `${siteUrl}/fr/services/core-web-vitals-performance/` },
  ];

  return (
    <SEO
      data={info}
      titleKey="services.cwv.meta.title"
      descriptionKey="services.cwv.meta.description"
      keywordsKey="services.cwv.meta.keywords"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      structuredData={jsonLd}
      schemaType="ProfessionalService"
    />
  );
};
